CREATE TABLE public.return_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid NOT NULL REFERENCES public.orders(id),user_id uuid NOT NULL,scenario text NOT NULL,description text NOT NULL,status text NOT NULL DEFAULT 'pending',decision_reason text,credit_decision text NOT NULL DEFAULT 'pending',refund_amount numeric NOT NULL DEFAULT 0,refund_status text NOT NULL DEFAULT 'not_recorded',reviewed_by uuid,created_at timestamptz NOT NULL DEFAULT now(),reviewed_at timestamptz);
GRANT SELECT ON public.return_requests TO authenticated; GRANT ALL ON public.return_requests TO service_role;
ALTER TABLE public.return_requests ENABLE ROW LEVEL SECURITY;
CREATE POLICY return_owner_read ON public.return_requests FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.return_request_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),return_id uuid NOT NULL REFERENCES public.return_requests(id),order_item_id uuid NOT NULL REFERENCES public.order_items(id),quantity integer NOT NULL CHECK(quantity>0),restocked boolean NOT NULL DEFAULT false,UNIQUE(return_id,order_item_id));
GRANT SELECT ON public.return_request_items TO authenticated; GRANT ALL ON public.return_request_items TO service_role;
ALTER TABLE public.return_request_items ENABLE ROW LEVEL SECURITY;
CREATE POLICY return_items_read ON public.return_request_items FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.return_requests r WHERE r.id=return_id AND (r.user_id=auth.uid() OR public.has_role(auth.uid(),'admin'))));
CREATE TABLE public.return_history(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),return_id uuid NOT NULL REFERENCES public.return_requests(id),action text NOT NULL,reason text NOT NULL,actor uuid,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.return_history TO authenticated; GRANT ALL ON public.return_history TO service_role;
ALTER TABLE public.return_history ENABLE ROW LEVEL SECURITY;
CREATE POLICY return_history_read ON public.return_history FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.return_requests r WHERE r.id=return_id AND (r.user_id=auth.uid() OR public.has_role(auth.uid(),'admin'))));
CREATE TRIGGER return_audit AFTER INSERT OR UPDATE ON public.return_requests FOR EACH ROW EXECUTE FUNCTION public.audit_row();
CREATE OR REPLACE FUNCTION public.submit_return(p_order uuid,p_scenario text,p_description text,p_items jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE o public.orders%rowtype; rid uuid; i jsonb; oi public.order_items%rowtype; already integer; BEGIN SELECT * INTO o FROM public.orders WHERE id=p_order AND user_id=auth.uid() FOR UPDATE; IF NOT FOUND OR o.status NOT IN ('delivered','return_requested') THEN RAISE EXCEPTION 'Only your delivered orders can be returned'; END IF; IF p_scenario NOT IN ('full','partial','damaged','wrong','defective','replacement') OR length(trim(p_description))<5 OR jsonb_array_length(p_items)=0 THEN RAISE EXCEPTION 'Invalid return details'; END IF; INSERT INTO public.return_requests(order_id,user_id,scenario,description) VALUES(o.id,auth.uid(),p_scenario,p_description) RETURNING id INTO rid; FOR i IN SELECT * FROM jsonb_array_elements(p_items) LOOP SELECT * INTO oi FROM public.order_items WHERE id=(i->>'itemId')::uuid AND order_id=o.id; IF NOT FOUND OR (i->>'quantity')::integer<=0 THEN RAISE EXCEPTION 'Invalid return item'; END IF; SELECT coalesce(sum(ri.quantity),0) INTO already FROM public.return_request_items ri JOIN public.return_requests r ON r.id=ri.return_id WHERE ri.order_item_id=oi.id AND r.status<>'rejected'; IF already+(i->>'quantity')::integer>oi.quantity THEN RAISE EXCEPTION 'Quantity already returned or requested'; END IF; INSERT INTO public.return_request_items(return_id,order_item_id,quantity) VALUES(rid,oi.id,(i->>'quantity')::integer); END LOOP; UPDATE public.orders SET status='return_requested' WHERE id=o.id; INSERT INTO public.return_history(return_id,action,reason,actor) VALUES(rid,'submitted',p_description,auth.uid()); RETURN rid; END $$;
REVOKE ALL ON FUNCTION public.submit_return(uuid,text,text,jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.submit_return(uuid,text,text,jsonb) TO authenticated;
CREATE OR REPLACE FUNCTION public.review_return(p_return uuid,p_approve boolean,p_restore boolean,p_restock boolean,p_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.return_requests%rowtype; o public.orders%rowtype; i record; cyc public.membership_cycles%rowtype; BEGIN IF auth.uid() IS NULL OR NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Forbidden'; END IF; IF length(trim(p_reason))<5 OR (NOT p_approve AND (p_restore OR p_restock)) THEN RAISE EXCEPTION 'Invalid return decision'; END IF; SELECT * INTO r FROM public.return_requests WHERE id=p_return FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Return not found'; END IF; IF r.status<>'pending' THEN RAISE EXCEPTION 'Return already reviewed'; END IF; SELECT * INTO o FROM public.orders WHERE id=r.order_id FOR UPDATE; IF p_restock AND r.scenario IN ('damaged','defective') THEN RAISE EXCEPTION 'Damaged or defective products cannot be restocked'; END IF; IF p_restore THEN IF o.membership_credit_status<>'consumed' OR EXISTS(SELECT 1 FROM public.membership_credit_ledger WHERE order_id=o.id AND kind='restore') THEN RAISE EXCEPTION 'No consumed credit available to restore'; END IF; SELECT * INTO cyc FROM public.membership_cycles WHERE id=o.membership_cycle_id FOR UPDATE; IF cyc.status<>'active' OR cyc.period_end<=now() THEN RAISE EXCEPTION 'Expired credits cannot be restored'; END IF; INSERT INTO public.membership_credit_ledger(user_id,membership_id,cycle_id,order_id,delta,kind,note,actor) VALUES(o.user_id,cyc.membership_id,cyc.id,o.id,1,'restore',p_reason,auth.uid()); END IF; IF p_restock THEN PERFORM set_config('sabtk.order_id',o.id::text,true); PERFORM set_config('sabtk.stock_kind','return_restock',true); PERFORM set_config('sabtk.stock_reason',p_reason,true); FOR i IN SELECT ri.id,ri.quantity,oi.product_id FROM public.return_request_items ri JOIN public.order_items oi ON oi.id=ri.order_item_id WHERE ri.return_id=r.id LOOP UPDATE public.products SET stock_quantity=stock_quantity+i.quantity WHERE id=i.product_id; UPDATE public.return_request_items SET restocked=true WHERE id=i.id; END LOOP; END IF; UPDATE public.return_requests SET status=CASE WHEN p_approve THEN 'approved' ELSE 'rejected' END,decision_reason=p_reason,credit_decision=CASE WHEN p_restore THEN 'restored' ELSE 'kept' END,reviewed_by=auth.uid(),reviewed_at=now() WHERE id=r.id; INSERT INTO public.return_history(return_id,action,reason,actor) VALUES(r.id,CASE WHEN p_approve THEN 'approved' ELSE 'rejected' END,p_reason,auth.uid()); IF NOT EXISTS(SELECT 1 FROM public.return_requests WHERE order_id=o.id AND status='pending') THEN UPDATE public.orders SET status=CASE WHEN EXISTS(SELECT 1 FROM public.return_requests WHERE order_id=o.id AND status='approved') THEN 'returned'::public.order_status ELSE 'delivered'::public.order_status END WHERE id=o.id; END IF; END $$;
REVOKE ALL ON FUNCTION public.review_return(uuid,boolean,boolean,boolean,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.review_return(uuid,boolean,boolean,boolean,text) TO authenticated;